// Scoring ICP (Ideal Customer Profile) du prospect.
// Les critères ICP sont à adapter. Le score par règles sert de base ;
// le champ "promptIA" est prêt à être envoyé à un nœud LLM (Claude/GPT) pour un résumé.
// Règle : une donnée absente n'est jamais devinée, elle est listée dans "donneesManquantes".
const ICP = {
  tranchesEffectif: ['11', '12', '21', '22', '31', '32'], // codes INSEE : 10 à 499 salariés
  postesCibles: ['directeur', 'directrice', 'head', 'responsable', 'ceo', 'cto', 'coo', 'fondateur', 'fondatrice'],
  nafCibles: ['62', '63', '70', '73'], // informatique, info, conseil, publicité
};
const lead = $('Formulaire de contact').first().json.body ?? {};
const ent = ($input.first().json.results ?? [])[0] ?? {};

const poste = String(lead.poste ?? '').toLowerCase();
const naf = String(ent.activite_principale ?? '');
const effectif = String(ent.tranche_effectif_salarie ?? '');

const criteres = {
  entrepriseTrouvee: Boolean(ent.siren),
  tailleCible: ICP.tranchesEffectif.includes(effectif),
  secteurCible: ICP.nafCibles.some((p) => naf.startsWith(p)),
  posteDecideur: ICP.postesCibles.some((p) => poste.includes(p)),
  emailPro: /@/.test(lead.email ?? '') && !/@(gmail|yahoo|hotmail|outlook)\./i.test(lead.email ?? ''),
};
const poids = { entrepriseTrouvee: 10, tailleCible: 25, secteurCible: 25, posteDecideur: 25, emailPro: 15 };
const score = Object.entries(criteres).reduce((s, [k, ok]) => s + (ok ? poids[k] : 0), 0);

const profil = {
  nom: lead.nom ?? '', email: lead.email ?? '', poste: lead.poste ?? '',
  entreprise: ent.nom_complet ?? lead.entreprise ?? '', siren: ent.siren ?? '',
  secteurNaf: naf, trancheEffectif: effectif, message: lead.message ?? '',
};
const donneesManquantes = Object.entries(profil).filter(([, v]) => !v).map(([k]) => k);

return [{ json: {
  ...profil, score, criteres,
  priorite: score >= 70 ? 'Haute' : score >= 40 ? 'Moyenne' : 'Basse',
  donneesManquantes: donneesManquantes.join(', '),
  promptIA: `Résume ce prospect B2B en 3 lignes et explique son score ICP (${score}/100). Ne complète aucune donnée absente.\n${JSON.stringify(profil)}`,
} }];

